        internal void Update()
        {

            long parentId = 0L;
            var parentType = orderParentType.Unknown;

            if (ReferenceEquals(m_parent.GetType(), typeof(ReportAnalyte)))
            {
                parentType = orderParentType.ReportAnalyte;
                parentId = ((ReportAnalyte)m_parent).ID;
            }
            else if (ReferenceEquals(m_parent.GetType(), typeof(ReportAnalytePanel)))
            {
                parentType = orderParentType.ReportAnalytePanel;
                parentId = ((ReportAnalytePanel)m_parent).Id;
            }
            else if (ReferenceEquals(m_parent.GetType(), typeof(Report)))
            {
                parentType = orderParentType.Report;
                parentId = ((Report)m_parent).ID;
            }

            if (!string.IsNullOrEmpty(m_externalId))
            {

                Report report = null;
                if (parentType == orderParentType.Report)
                {
                    report = (Report)m_parent;
                }
                else if (parentType == orderParentType.ReportAnalytePanel)
                {
                    report = ((ReportAnalytePanel)m_parent).Parent;
                }
                else if (parentType == orderParentType.ReportAnalyte)
                {
                    ReportAnalyte analyte = (ReportAnalyte)m_parent;
                    if (ReferenceEquals(analyte.Parent.GetType(), typeof(Report)))
                    {
                        report = (Report)analyte.Parent;
                    }
                    else
                    {
                        report = ((ReportAnalytePanel)analyte.Parent).Parent;
                    }
                }

                if (report.FindCommentGroup(m_externalId) == null)
                {
                    report.m_reportCommentGroups.Add(new ReportCommentGroup(report, m_externalId, report.FindCommentGroupNextPosition()));
                }

            }

            var da = new DataWrapper(Configuration.ConnectionString);
            var paramList = new List<DbParameter>();

            paramList.Add((DbParameter)da.CreateParameter("@ReportCommentId", DbType.Int64, m_id, ParameterDirection.InputOutput));
            paramList.Add((DbParameter)da.CreateParameter("@ParentType", DbType.Int32, parentType));
            paramList.Add((DbParameter)da.CreateParameter("@ParentId", DbType.Int64, parentId));
            paramList.Add((DbParameter)da.CreateParameter("@Text", DbType.String, m_text));
            // AG - Comments
            paramList.Add((DbParameter)da.CreateParameter("@ExternalId", DbType.String, m_externalId));
            paramList.Add((DbParameter)da.CreateParameter("@IsAutoAdded", DbType.Boolean, m_isAutoAdded));
            paramList.Add((DbParameter)da.CreateParameter("@ExtCommentCode", DbType.String, m_externalCommentCode));
            paramList.Add((DbParameter)da.CreateParameter("@ExtCommentType", DbType.Int32, m_externalCommentType));
            paramList.Add((DbParameter)da.CreateParameter("@Priority", DbType.Int32, m_priority));

            DbParameter[] @params = paramList.ToArray();

            m_id = Conversions.ToLong(da.ExecuteNonQuery("lis_ReportComment_Save", @params)["@ReportCommentId"].Value);

            // NA: Get the list of AuditItem in this object after issuing the Clean so all properties are correctly populated.
            m_auditItemList.AddRange(GetAuditItemsAndClean(true));
            // Me.FlagClean(True)
            if (m_internalNoteId > -1)
            {
                SaveInternalNote(parentId, (int)parentType);
            }

        }

