            paramList.Add((DbParameter)da.CreateParameter("@ReportCommentId", DbType.Int64, m_id));
            paramList.Add((DbParameter)da.CreateParameter("@ParentType", DbType.Int32, parentType));
            paramList.Add((DbParameter)da.CreateParameter("@ParentId", DbType.Int64, parentId));
            paramList.Add((DbParameter)da.CreateParameter("@InternalNoteID", DbType.String, m_internalNoteId));
            paramList.Add((DbParameter)da.CreateParameter("@InternalNoteText", DbType.String, m_internalNoteText));
            if (!(CurrentUser == null))
            {
                paramList.Add((DbParameter)da.CreateParameter("@CreatedBy", DbType.String, CurrentUser.Name));
            }
            else
            {
                paramList.Add((DbParameter)da.CreateParameter("@CreatedBy", DbType.String, ""));
